        SamplingService.BatchMergeOutcome outcome = samplingService.mergeBatch(request);
        return ResponseEntity.status(outcome.status()).body(outcome.body());
    }

    /**
     * 冲突簇人工裁决：待裁决簇按指定内容裁决，成员观测统一置为已合并。
     */
